export const AD_RECIPIENT='ad@venturesquare.net';
export function adInquiryForm(){return `<form id="ad-inquiry-form"><p class="ad-form-intro">행사나 지원사업을 게임 위아래 배너에 소개할 수 있습니다. 참가자가 데모데이에서 상을 받거나 새 거래처를 만나는 일처럼, 프로그램을 게임 속 좋은 소식으로 풀어내는 협업도 가능합니다.</p><div class="ad-examples"><figure><img src="assets/guide-decision.jpg?v=14" alt="실제 인게임 사건 선택 화면"><figcaption><small>실제 플레이 화면</small>행사와 연결되는 선택 장면</figcaption></figure><figure><img src="assets/guide-schedule.jpg?v=14" alt="실제 인게임 작업실과 광고 영역"><figcaption><small>실제 플레이 화면</small>작업실 안의 광고 영역</figcaption></figure></div><p class="ad-example-note">실제 게임 화면을 바탕으로 행사 시나리오와 배너 위치를 함께 기획합니다.</p><label>기관·회사명<input class="field" name="organization" autocomplete="organization" maxlength="100" required></label><label>회신 이메일<input class="field" name="email" type="email" autocomplete="email" maxlength="180" required></label><label>희망 홍보 기간 <small>(선택)</small><input class="field" name="period" placeholder="예) 3월 중 2주간" maxlength="100"></label><label>게임 시나리오 협업<select class="field" name="collaboration"><option>상담 후 결정</option><option>배너 광고</option><option>게임 시나리오 협업</option><option>배너와 시나리오 모두</option></select></label><label>문의 내용<textarea class="field" name="message" rows="5" maxlength="3000" placeholder="행사·사업 이름과 소개하고 싶은 내용을 적어 주세요." required></textarea></label><div class="ad-recipient"><span>받는 주소 <strong>${AD_RECIPIENT}</strong></span><button class="quiet" type="button" data-action="ad-copy-address">주소 복사</button></div><div class="ad-form-actions"><button class="primary" type="button" data-action="ad-mail">메일 앱에서 보내기</button><button class="quiet" type="button" data-action="ad-copy-message">문의 내용 복사</button></div><p id="ad-form-status" role="status"></p><textarea id="ad-copy-fallback" class="field" rows="5" readonly hidden aria-label="복사할 문의 내용"></textarea><small class="ad-origin">인게임 화면 · 원본 게임 ‘사업 2회차’ · CC BY 4.0</small></form>`;}
export function inquiryPayload(values){const organization=String(values.organization||'').trim(),email=String(values.email||'').trim(),message=String(values.message||'').trim();return {subject:`[모두의 창업 광고 문의] ${organization}`,body:[`기관·회사명  ${organization}`,`회신 이메일  ${email}`,`희망 홍보 기간  ${String(values.period||'').trim()||'미정'}`,`게임 시나리오 협업  ${values.collaboration||'상담 후 결정'}`,'',message].join('\r\n')};}
export function inquiryMailto(payload){return `mailto:${AD_RECIPIENT}?subject=${encodeURIComponent(payload.subject)}&body=${encodeURIComponent(payload.body)}`;}
